local GameUtils = GameUtils

local PhysicalStrengthDialog = Class(NAME)
function PhysicalStrengthDialog:__init()
    self.timer = nil
    self.freeHpNum = nil
    self.nextFreeHpRecoveryTime = nil
    self.max = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 13).num
    self.hpValue = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 12).num
    self.recoveryInterval = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 11).num)
    self.twoThirdsSeconds = (self.recoveryInterval * 2 / 3)
    self.oneThirdsSeconds = (self.recoveryInterval * 1 / 3)
    self.BtnTag = {}
end

function PhysicalStrengthDialog:__delete()
    self.controller = nil
    self.timer = nil
    self.freeHpNum = nil
    self.nextFreeHpRecoveryTime = nil
    self.getStatus = nil
    self.max = nil
    self.recoveryInterval = nil
    self.twoThirdsSeconds = nil
    self.oneThirdsSeconds = nil
    self.hpValue = nil
end

function PhysicalStrengthDialog:Awake()
    for index = 1, 2 do
        local btnNode = self['BtnPower'..index]
        SetButtonAction(btnNode, function()
            if checkInt(checkTable(self.BtnTag[index]).status) == 3 then
                self:GoToGetHp(index)
            end
        end)
    end
    SetButtonAction(self.BtnCat, Bind(self, self.OnClickCatNode))
end

function PhysicalStrengthDialog:Refresh()
    self:RefreshCurrencyBarInfo()
    GameUtils.Request(
            Interfaces.GrowthFundFreeHpInfo,
            {  },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    local nextFreeHpRecoveryTime =  response.data.freeHpRestoreTimes - math.floor(response.data.freeHpRestoreTimes/self.recoveryInterval) * self.recoveryInterval
                    self.freeHpNum = response.data.freeHpNum
                    AppService:GetInstance():SetFreeHpCountDown({--开始倒计时并维护自己的数据
                        freeHpNum = self.freeHpNum, --可领取的次数
                        freeHpRestoreTimes = checkNumber(response.data.freeHpRestoreTimes), --体力恢复满倒计时  如0——>2剩余时间
                        nextFreeHpRecoveryTime = nextFreeHpRecoveryTime--下次一恢复剩余时间  如0-->1剩余时间
                    })
                    self.nextFreeHpRecoveryTime = response.data.freeHpRestoreTimes
                    KTool.SetActive(self.CatSpine, true)
                    self:SetLeftSecond(response.data.freeHpRestoreTimes)
                    self:PlayCatSpine()
                end
            end
    )
end

function PhysicalStrengthDialog:RefreshCurrencyBarInfo()
    CfUtils.RefreshTopGoods({Constants.Currency.HpId})
end

function PhysicalStrengthDialog:GoToGetHp(index)
    GameUtils.Request(Interfaces.GrowthFundFreeHpDraw, {}, function(request, response)
        if checkInt(response.errCode) == 0 then
            self.freeHpNum = self.freeHpNum - 1
            GameUtils.SetRedPointNum(Constants.RedPointConst.PhysicalStrength, self.freeHpNum)
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.PhysicalStrength)
            AppService:GetInstance():UpdateRecoveryValueFreeHp(self.freeHpNum)
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComponent.playerDojo.nextHpSeconds = response.data.hpInfo.lastCdTime--体力恢复时间数据维护

            local changeIndex = self.BtnTag[index].index
            for idx, btnDt in ipairs(self.BtnTag) do
                if idx == index then
                    btnDt.index = #self.BtnTag
                elseif btnDt.index > changeIndex then
                    btnDt.index = btnDt.index - 1
                end
            end
            self.nextFreeHpRecoveryTime = AppService:GetInstance():GetNextFreeHpRecoveryTime() + (self.max - self.freeHpNum - 1) * self.recoveryInterval
            self.keepRetainState = false
            self:SetLeftSecond(self.nextFreeHpRecoveryTime, true)

            local rewards = {
                {
                    goodsId = Constants.Currency.HpId,
                    num = self.hpValue
                }
            }
            GoodsUtils.DrawRewards(rewards, true)
            UIModule.OpenDialog(
                    {
                        id = Constants.UITypeIds.UICommonRewardPop,
                        parameters = {
                            rewards = rewards,
                            cb = function()
                                self:PlayParticleAnim(index)
                                self:PlayCatSpine(true)
                                -- 是否首次领取
                                local isOpen = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 38).num
                                if (not GameUtils.IsPCPlatform()) and checkInt(isOpen) == 1 then
                                    if CfUtils.GetLocalData('FirstGetPhysicalStrength', "0") == '0' then
                                        CfUtils.WriteLocalData('FirstGetPhysicalStrength', 1)
                                        CfUtils.DialogOpen(Constants.UITypeIds.PushSuggestionDialog)
                                    end
                                end
                            end,
                        },
                    }
            )

        end
    end
    )
end

---设置倒计时
---@param leftTime number 倒计时长
function PhysicalStrengthDialog:SetLeftSecond(leftTime, playJumpAnim)
    if self.freeHpNum == self.max or checkInt(leftTime) == 0 then
        self:UpdateTime(0)
        self:UpdateBtnNodeByIndex(1)
        -- self:UpdateBtnNodeByIndex(2)
        if self.freeHpNum == self.max then
            self:PlayCatSpine()
        end
        return
    end

    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end

    self.timer = CDTimerModule:AddCD(1, function (count, id)
        self.nextFreeHpRecoveryTime = count

        self:UpdateTime(count)

        if not self.keepRetainState then
            self:UpdateBtnNodeByIndex(1, self.recoveryInterval - count)
            -- self:UpdateBtnNodeByIndex(2, self.recoveryInterval - count)
        end
        if count <= 0 then
            cs_coroutine.start(function()
                cs_coroutine.yield_return(Yielders.EndOfFrame)
                --self.nextFreeHpRecoveryTime = AppService:GetInstance():GetNextFreeHpRecoveryTime()
                self.freeHpNum = AppService:GetInstance():GetFreeHpNum()
                self.nextFreeHpRecoveryTime = (self.max - self.freeHpNum) * self.recoveryInterval
                self:SetLeftSecond(self.nextFreeHpRecoveryTime)
            end)
        end
    end, leftTime, true, true, true)
end

