function PhysicalStrengthDialog:UpdateBtnNodeByIndex(index, passTime)
    index = 1
    passTime = checkNumber(passTime)
    local btnNode    = self["BtnPower"..index]
    local getNode    = self['Imgreceive' .. index]
    CfUtils.FillText(self.TxtNum1.gameObject , self.freeHpNum) 
    local btnIndex   = checkTable(self.BtnTag[index]).index or index
    local isCanGet   = self.freeHpNum >= btnIndex
    local isProgress = (self.freeHpNum + 1) == btnIndex and passTime >= self.oneThirdsSeconds

    if KTool.IsActive(getNode) ~= isCanGet then
        KTool.SetActive(getNode, isCanGet)
    end

    if KTool.IsActive(btnNode) ~= (isCanGet or isProgress) then
        KTool.SetActive(btnNode, isCanGet or isProgress)
    end

    if isCanGet then
        self:SetBtnStatus(btnNode, 3, index, btnIndex)
    elseif isProgress then
        if passTime >= self.twoThirdsSeconds then
            self:SetBtnStatus(btnNode, 2, index, btnIndex)
        else
            self:SetBtnStatus(btnNode, 1, index, btnIndex)
        end
    end
end

function PhysicalStrengthDialog:SetBtnStatus(btnNode, status, index, btnIndex)
    local oldStatus = checkInt(checkTable(self.BtnTag[index]).status)
    if oldStatus == checkInt(status) then return end

    self.BtnTag[index] = {status = status, index = btnIndex}
    CfUtils.SetUISwitchImage(btnNode, status)
end

function PhysicalStrengthDialog:UpdateTime(leftTime)
    KTool.SetActive(self.TxtTime, leftTime > 0)
    KTool.SetActive(self.Finished, leftTime <= 0)
    KTool.SetActive(self.UnFinished, leftTime > 0)
    if leftTime > 0 then
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(leftTime))
    end
end

function PhysicalStrengthDialog:OnClickCatNode()
    if self.freeHpNum < 2 then
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_button_supply)
    end
end

function PhysicalStrengthDialog:PlayCatSpine(playJumpAnim)
    if checkBool(playJumpAnim) and self.freeHpNum == 3 then
        cs_coroutine.start(function ()
            local track = CfUtils.PlaySpine(self.CatSpine, "Jump", false)
            CfUtils.PlayAnimator(self.EnergyBox, "Jump")
            cs_coroutine.yield_return(WaitForSpineAnimationComplete(track));
            CfUtils.PlaySpine(self.CatSpine, "Rummage", true)
            CfUtils.PlayAnimator(self.EnergyBox, "Rummage")
        end)
    elseif self.freeHpNum == 4 then
        CfUtils.PlaySpine(self.CatSpine, "Idle", true)
        CfUtils.PlayAnimator(self.EnergyBox, "Idle")
    else
        CfUtils.PlaySpine(self.CatSpine, "Rummage", true)
        CfUtils.PlayAnimator(self.EnergyBox, "Rummage")
    end
end

function PhysicalStrengthDialog:PlayParticleAnim(index)
    local parSysParent = self['Particle_'..index]
    local parSysNode = parSysParent:Find("PtcBoom")
    local parSys     = KTool.GetComponent(parSysNode.gameObject, typeof(CS.Engine.UI.ParticleTargetMove))
    ---@type UINavigatorBar
    local navigatorScr = CfUtils.GetLuaScr(CS.UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
    if parSys then
        parSys:Play( navigatorScr.healthNodes[1].transform:Find("Image").transform.position , 30)
    end
end

function PhysicalStrengthDialog:OnDestroy()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PhysicalStrengthDialog